/**
 * Global Array to store selected Instruments
 */
const selectedInstruments = [];

/**
 * Amount of max possible Instrument-Selections
 */
const numberOfPossibleSelections = 8;

/**
 * ChartTool Url with InstrumentType-Parameter for Shares
 */
const chartToolUrl = '/charttool';



/***
 * Updates the selected InstrumentItem in the global Selection-Array
 */
const updateSelectedInstruments = (instrumentString, element) => {
    if(selectedInstruments.includes(instrumentString)) {
        const instrumentPosition = selectedInstruments.indexOf(instrumentString);

        selectedInstruments.splice(instrumentPosition, 1);
    }
    else {
        if(checkIfInstrumentSelectionIsAllowed(instrumentString)) {
            selectedInstruments.push(instrumentString);
        }
        else {
            element.checked = false;
            element.style.outline = '1px solid ##dc3545';
        }
    }
}

/**
 * Updates the Compare-Buttons Target based on selected Instruments
 */
const updateSubmitButtonLink = (instrumentType) => {
    const compareButton = document.querySelector(`#chartcompare-button__${instrumentType}`);

    let chartToolHref = `${chartToolUrl}?instrumentType=${instrumentType}`;

    if(selectedInstruments.length > 0) {
        chartToolHref += `&instrumentStrings=${selectedInstruments.join(',')}`;
    }

    compareButton.setAttribute('href', chartToolHref);
}

/**
 * Checks if InstrumentString fulfills some criteria to be added
 * @returns bool
 */
const checkIfInstrumentSelectionIsAllowed = (instrumentString) => {

    // Is Max. assignable Instrument Limit reached
    if(selectedInstruments.length >= numberOfPossibleSelections) {
        return false;
    }

    // Min-Length
    if(instrumentString.length < 20) {
        return false;
    }

    // Format with separators
    if((instrumentString.split(':').length) !== 5) {
        return false;
    }

    return true;
}

/**
 * EventListener to trigger InstrumentString Updates when clicked
 */
const addEventListenerForSelections = () => {
    document.querySelectorAll('.chartcompare-checkbox').forEach((element) => {
        element.addEventListener('change', () => {
            const instrumentString = element.getAttribute('data-instrumentstring');
            const instrumentType = element.getAttribute('data-type');

            if(instrumentString.length !== 0) {
                updateSelectedInstruments(instrumentString, element);
                updateSubmitButtonLink(instrumentType);
            }
        });
    });
}

/**
 * Wait until DOM is ready and add EventListeners
 */
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        addEventListenerForSelections();
    }, 500);
})

